"""Writes the results of prep.py: the level table, the sound credits, and a report."""

import json

LEVELS_HEADER = """\
// Generated by scripts/audio/prep.py from src/sound/sounds.json. Do not edit this file by hand.
// Run `python3 scripts/audio/prep.py` again after a change to sounds.json.

/** The measured values and the play gain of one processed file. */
export type ClipLevel = {
  /** The path below `public/` and below the base URL. */
  readonly file: string;
  /** The length in seconds, after the cut and the silence trim. */
  readonly seconds: number;
  /** The integrated loudness I in LUFS. It is not valid below 0.4 s. */
  readonly lufs: number;
  /** The true peak TP in dBTP. */
  readonly truePeak: number;
  /** The rule that set the gain: -18 - I ('loudness'), -1 - TP ('peak'), or -6 - TP ('short'). */
  readonly rule: 'loudness' | 'peak' | 'short';
  /** The decrease in dB that keeps the file from being louder than the snap. */
  readonly snapLimitDb: number;
  /** The play gain in dB. The sound module applies it. */
  readonly gainDb: number;
  /** The maximum momentary loudness M in LUFS after the gain, with the file padded to 0.4 s. */
  readonly maxMomentary: number;
};

/** A file and its play gain. */
export type Clip = Pick<ClipLevel, 'file' | 'gainDb'>;
"""


def _ts(value):
    return json.dumps(value, ensure_ascii=False)


def _object(fields):
    return "{ " + ", ".join(f"{key}: {_ts(value)}" for key, value in fields.items()) + " }"


def write_levels(path, levels, slots):
    clips = "\n".join(f"  {_ts(clip_id)}: {_object(level)}," for clip_id, level in levels.items())
    shipped = "\n".join(
        f"  {_ts(slot['id'])}: {_object({k: levels[slot['pick']][k] for k in ('file', 'gainDb')})},"
        for slot in slots
    )
    path.write_text(
        LEVELS_HEADER
        + "\n/** One line for each processed file: the shipped files and the listening page candidates. */\n"
        + "export const CLIPS: Readonly<Record<string, ClipLevel>> = {\n"
        + clips
        + "\n};\n\n/** The shipped file of each slot. */\nexport const SHIPPED = {\n"
        + shipped
        + "\n} as const satisfies Readonly<Record<string, Clip>>;\n"
    )


def _time(seconds):
    return f"{int(seconds // 60)}:{seconds % 60:04.1f}"


def _change(clip):
    cut = clip.get("cut")
    convert = "Converted to mono WAV, 16-bit, 44.1 kHz, and removed the silence at the start."
    if cut is None:
        return convert
    end = cut["start"] + cut["duration"]
    fades = f"a {cut.get('fadeOut', 0.2)} s fade-out"
    if cut["start"] > 0:
        fades = f"a 0.05 s fade-in and {fades}"
    return f"Cut {_time(cut['start'])} to {_time(end)} of the source file, with {fades}. {convert}"


def write_credits(path, manifest, levels):
    """Replaces the "sound" entries. One entry for each work, with the shipped files of that work."""
    credits = json.loads(path.read_text())
    works = {}
    for clip_id, level in levels.items():
        if not level["file"].startswith("sounds/"):
            continue
        clip = manifest["clips"][clip_id]
        key = (clip["title"], clip["author"], clip["licence"], clip["page"])
        work = works.setdefault(key, {"files": [], "changes": []})
        work["files"].append(level["file"])
        if _change(clip) not in work["changes"]:
            work["changes"].append(_change(clip))
    entries = [entry for entry in credits["entries"] if entry["kind"] != "sound"]
    for (title, author, licence, page), work in sorted(works.items()):
        entries.append(
            {
                "kind": "sound",
                "title": title,
                "author": author,
                "licence": licence,
                "url": page,
                "files": sorted(work["files"]),
                "change": " ".join(work["changes"]),
            }
        )
    credits["entries"] = entries
    path.write_text(json.dumps(credits, indent=2, ensure_ascii=False) + "\n")


def print_report(levels, slots):
    picks = {slot["pick"]: slot["id"] for slot in slots}
    print(f"{'clip':24} {'slot':6} {'s':>6} {'I':>6} {'TP':>6} {'rule':9} {'gain':>6} {'snap':>5} {'M':>6}")
    for clip_id, level in levels.items():
        print(
            f"{clip_id:24} {picks.get(clip_id, '-'):6} {level['seconds']:6.3f} {level['lufs']:6.1f}"
            f" {level['truePeak']:6.1f} {level['rule']:9} {level['gainDb']:6.1f}"
            f" {-level['snapLimitDb']:5.1f} {level['maxMomentary']:6.1f}"
        )
